local HedgeHookMaker = {}
local PRODUCTS = {
    iron_hedge_hook = { name = "Železni kavelj za živo mejo", ironCost = 2, woodCost = 1, leatherCost = 1, time = 5, cost = 145, prestige = 3, happiness = 1, description = "Železni kavelj za oblikovanje žive meje." },
    bronze_hedge_hook = { name = "Bronast kavelj za živo mejo", bronzeCost = 2, ironCost = 1, woodCost = 1, leatherCost = 1, time = 7, cost = 350, prestige = 5, happiness = 2, description = "Bronast kavelj za trši les." },
    silver_hedge_hook = { name = "Srebrni kavelj za živo mejo", silverCost = 2, bronzeCost = 1, ironCost = 1, woodCost = 1, leatherCost = 1, time = 11, cost = 840, prestige = 10, happiness = 3, description = "Srebrni kavelj za plemiške vrtove." },
    gilded_hedge_hook = { name = "Pozlačeni kavelj za živo mejo", goldCost = 1, silverCost = 2, bronzeCost = 1, woodCost = 1, leatherCost = 1, time = 15, cost = 1800, prestige = 19, happiness = 4, description = "Pozlačeni kavelj za dvorne vrtove." },
    jewel_set_hedge_hook = { name = "Draguljasti kavelj za živo mejo", goldCost = 2, silverCost = 2, jewelCost = 1, bronzeCost = 1, woodCost = 1, leatherCost = 1, time = 19, cost = 3900, prestige = 35, happiness = 6, description = "Draguljasti kavelj za kraljeve vrtove." },
    royal_sovereign_hedge_hook = { name = "Kraljevski suvereni kavelj za živo mejo", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 26, cost = 8300, prestige = 67, happiness = 12, description = "Suvereni kavelj z biseri za krono." },
}
local BUILDINGS = {
    hedge_workshop = { name = "Kaveljska delavnica", cost = { gold = 330, wood = 170, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    hedge_house = { name = "Kaveljska hiša", cost = { gold = 1200, wood = 350, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_hedge_atelier = { name = "Mojstrski kaveljski atelje", cost = { gold = 3000, wood = 410, stone = 515, silver = 35, gold = 7 }, upkeep = 71, qualityBonus = 30 },
    sovereign_hedge_palace = { name = "Suverena kaveljska palača", cost = { gold = 12900, wood = 620, stone = 825, gold = 82, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
HedgeHookMaker.ironStock = 12; HedgeHookMaker.bronzeStock = 10; HedgeHookMaker.woodStock = 14; HedgeHookMaker.leatherStock = 10; HedgeHookMaker.silverStock = 8; HedgeHookMaker.goldStock = 6; HedgeHookMaker.jewelStock = 4; HedgeHookMaker.pearlStock = 4
HedgeHookMaker.productStock = {}; HedgeHookMaker.buildings = {}; HedgeHookMaker.maker = nil; HedgeHookMaker.activeMaking = {}; HedgeHookMaker.totalProducts = 0; HedgeHookMaker.dayTimer = 0
function HedgeHookMaker.init() HedgeHookMaker.ironStock=12; HedgeHookMaker.bronzeStock=10; HedgeHookMaker.woodStock=14; HedgeHookMaker.leatherStock=10; HedgeHookMaker.silverStock=8; HedgeHookMaker.goldStock=6; HedgeHookMaker.jewelStock=4; HedgeHookMaker.pearlStock=4; HedgeHookMaker.productStock={}; HedgeHookMaker.buildings={}; HedgeHookMaker.maker=nil; HedgeHookMaker.activeMaking={}; HedgeHookMaker.totalProducts=0; HedgeHookMaker.dayTimer=0; print("[HedgeHookMaker] Royal Hedge Hook Maker System initialized (6 products, 4 buildings)") end
function HedgeHookMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; HedgeHookMaker.maker={name=n or ("Kaveljar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kaveljar najet: %s (spretnost: %d)",HedgeHookMaker.maker.name,s),"success") end; return true end
function HedgeHookMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function HedgeHookMaker.build(id) local ok,e=HedgeHookMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(HedgeHookMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function HedgeHookMaker.getQualityBonus() local b=0; for _,bd in ipairs(HedgeHookMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function HedgeHookMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and HedgeHookMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and HedgeHookMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and HedgeHookMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and HedgeHookMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and HedgeHookMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and HedgeHookMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and HedgeHookMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and HedgeHookMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #HedgeHookMaker.buildings==0 then return false,"Potrebna kaveljska delavnica" end; if not HedgeHookMaker.maker then return false,"Potreben kaveljar" end; return true end
function HedgeHookMaker.make(pt,qty) qty=qty or 1; local ok,e=HedgeHookMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then HedgeHookMaker.ironStock=HedgeHookMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then HedgeHookMaker.bronzeStock=HedgeHookMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then HedgeHookMaker.woodStock=HedgeHookMaker.woodStock-d.woodCost*qty end; if d.leatherCost then HedgeHookMaker.leatherStock=HedgeHookMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then HedgeHookMaker.silverStock=HedgeHookMaker.silverStock-d.silverCost*qty end; if d.goldCost then HedgeHookMaker.goldStock=HedgeHookMaker.goldStock-d.goldCost*qty end; if d.jewelCost then HedgeHookMaker.jewelStock=HedgeHookMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then HedgeHookMaker.pearlStock=HedgeHookMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if HedgeHookMaker.maker then t=math.max(1,t-math.floor(HedgeHookMaker.maker.skill/13)) end; table.insert(HedgeHookMaker.activeMaking,{id="hedge_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function HedgeHookMaker.completeMaking(m) local q=1.0+(HedgeHookMaker.getQualityBonus()/100); if HedgeHookMaker.maker then q=q+(HedgeHookMaker.maker.skill/140) end; q=math.min(2.5,q); HedgeHookMaker.productStock[m.productType]=(HedgeHookMaker.productStock[m.productType] or 0)+m.quantity; HedgeHookMaker.totalProducts=HedgeHookMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if HedgeHookMaker.maker then HedgeHookMaker.maker.itemsMade=HedgeHookMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then HedgeHookMaker.maker.skill=math.min(100,HedgeHookMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kavelj izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"hedge.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function HedgeHookMaker.update(dt) if not _G.state then return end; HedgeHookMaker.dayTimer=HedgeHookMaker.dayTimer+dt; if HedgeHookMaker.dayTimer>=30 then HedgeHookMaker.dayTimer=0; for i=#HedgeHookMaker.activeMaking,1,-1 do local m=HedgeHookMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then HedgeHookMaker.completeMaking(m); table.remove(HedgeHookMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(HedgeHookMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if HedgeHookMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function HedgeHookMaker.getStats() return {ironStock=HedgeHookMaker.ironStock,bronzeStock=HedgeHookMaker.bronzeStock,woodStock=HedgeHookMaker.woodStock,leatherStock=HedgeHookMaker.leatherStock,silverStock=HedgeHookMaker.silverStock,goldStock=HedgeHookMaker.goldStock,jewelStock=HedgeHookMaker.jewelStock,pearlStock=HedgeHookMaker.pearlStock,productStock=HedgeHookMaker.productStock,numBuildings=#HedgeHookMaker.buildings,hasMaker=HedgeHookMaker.maker~=nil,makerName=HedgeHookMaker.maker and HedgeHookMaker.maker.name or "—",makerSkill=HedgeHookMaker.maker and HedgeHookMaker.maker.skill or 0,activeMaking=#HedgeHookMaker.activeMaking,totalProducts=HedgeHookMaker.totalProducts} end
return HedgeHookMaker
